def copy_stakes(apps, schema_editor):
    """Give each battle's one stake a row of its own."""
    # Check keys as each row is written, so no check is left queued for
    # the schema changes that follow in this transaction.
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")
    Battle = apps.get_model("n26", "Battle")
    BattleStake = apps.get_model("n26", "BattleStake")
    BattleStake.objects.bulk_create(
        BattleStake(
            battle_id=battle.pk,
            asset_id=battle.stake_id,
            awarded_to_id=battle.stake_awarded_to_id,
            transfer_mark=battle.stake_transfer_mark,
        )
        for battle in Battle.objects.filter(stake__isnull=False).iterator()
    )


def copy_stakes_back(apps, schema_editor):
    """Put a battle's first stake back on the battle. Any others are lost."""
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")
    Battle = apps.get_model("n26", "Battle")
    BattleStake = apps.get_model("n26", "BattleStake")
    for stake in BattleStake.objects.order_by("-created", "-id").iterator():
        Battle.objects.filter(pk=stake.battle_id).update(
            stake_id=stake.asset_id,
            stake_awarded_to_id=stake.awarded_to_id,
            stake_transfer_mark=stake.transfer_mark,
        )


